// assets/profile-core.js is the ENGINE's rules (profile.ts + profile_data.ts) for the browser, generated by tools/make-profile-core.mjs. It must be exactly what
// the generator produces from the engine's files, and it must decide exactly as the engine does (the engine's own fixtures are replayed through it).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
import { buildProfileCore } from '../tools/make-profile-core.mjs';

const read = p => fs.readFileSync(new URL(`../${p}`, import.meta.url), 'utf8');
const par = JSON.parse(read('tests/fixtures/profile-parity.json'));
function load() { const window = {}; vm.runInNewContext(read('assets/profile-core.js'), { window, TextEncoder }); return window.ryagramProfile; }
const P = load();
const plain = x => JSON.parse(JSON.stringify(x));
const refused = p => { try { P.validateProfile(p); return null; } catch (e) { assert.ok(e instanceof P.ProfileError); return e.errors; } };

test('GENERATED: assets/profile-core.js is exactly what the generator builds from the engine files (rebuild with node tools/make-profile-core.mjs)', () => {
  assert.equal(read('assets/profile-core.js').replace(/\r\n/g, '\n'), buildProfileCore());
});

test('PARITY: every preset compiles to the same story, changed paths and warnings as the engine', () => {
  assert.ok(par.compiled.length >= 30);
  for (const c of par.compiled) {
    const { story, report } = P.applyProfile(par.presets[c.preset], par.samples[c.sample], c.mode);
    assert.deepEqual(plain(story), c.story, `${c.preset} on ${c.sample} (${c.mode})`);
    assert.deepEqual(plain(report.changed), c.changed, `${c.preset} changed`);
    assert.deepEqual(plain(report.warnings), c.warnings, `${c.preset} warnings`);
  }
});

test('PARITY: the colour guards say the same sentences, and shape decisions match', () => {
  for (const r of par.refused) assert.deepEqual(plain(refused(r.profile)), r.errors, r.name);
  for (const s of par.shape) assert.equal(refused(s.profile) === null, s.accepted, s.name);
});

test('PARITY: presets are fork-able and valid, and a rogue key is refused with the engine\'s sentence', () => {
  assert.deepEqual(plain(P.listPresets().map(p => p.id).sort()), ['bold-social', 'clean-light', 'print-mono', 'warm-documentary', 'wtds-classic']);
  for (const p of P.listPresets()) assert.equal(P.forkPreset(p.id, 'mine').based_on, p.id);
  const bad = plain(par.presets['clean-light']); bad.look.axis = 1;
  assert.match(refused(bad).join(), /unknown key 'axis'.*this object accepts/);
});

test('NO SECOND VALIDATOR: no other asset defines colour or shape rules (the editor calls window.ryagramProfile)', () => {
  for (const f of ['assets/app-looks.js', 'assets/app-library.js', 'assets/app-data.js']) {
    if (!fs.existsSync(new URL(`../${f}`, import.meta.url))) continue;
    assert.doesNotMatch(read(f), /dE apart|MIN_RAMP_SPAN|contrast ratio|function lab\(/, f);
  }
});
